const invite=read('engines/swimmer-invite-bn.js'),portal=read('swimmer-portal.js'),html=read('swimmer-portal.html'),sql=read('supabase/20260824_secure_swimmer_portal.sql'),qr=read('vendor/qrcode.min.js');
