(async()=>{const payload=M.swimmerInviteBN.payloadFor(athlete,roll);assert.equal(payload.schema,'msos-swimmer-portal-v5');assert.equal(payload.session.id,roll.id);assert.equal(payload.session.date,'2026-08-15');assert.equal(state.settings.selectedSessionId,live.id,'previewing an old session must not change live selected Training session');assert.equal(payload.athlete.full_name,'Matthew Test');assert.equal(Object.hasOwn(payload.athlete,'date_of_birth'),false);assert.equal(payload.session.blocks[0].items[0].label,'6 x 100 Free');assert.deepEqual(M.swimmerInviteBN.sessionsFor(athlete).map(s=>s.id),[live.id,remote.id,roll.id]);const history=await M.swimmerInviteBN.buildHistory(athlete,live,{strict:true});assert.equal(history.length,2);const remoteHistory=history.find(x=>x.session.id===remote.id),rollHistory=history.find(x=>x.session.id===roll.id);assert.equal(remoteHistory.participation.source,'remote');assert.equal(remoteHistory.participation.label,'Completed remotely');assert.equal(remoteHistory.finish.payload.rpe,7);assert.equal(rollHistory.participation.source,'aquagym');assert.equal(rollHistory.participation.label,'Attended at AquaGym');const QR=require(path.join(root,'vendor/qrcode.min.js'));const url='https://andymclay5-web.github.io/McLay-Swimming-OS/swimmer-portal.html?invite='+'a'.repeat(64),matrix=QR._matrix(url),bits=matrix.map(r=>r.map(x=>x?'1':'0').join('')).join('\n');assert.equal(matrix.length,49);assert.equal(crypto.createHash('sha256').update(bits).digest('hex'),'e0dab28bb09a51227681c8a2dd24b687a07c10e4e4f9a3accdb6752d06462f46');console.log('SWIMMER_SECURE_PREVIEW_STATIC_PASS inline-no-popup history-from-roll-and-remote-finish old-session-isolated dob-omitted invite-one-scan bundled-qr-deterministic');})().catch(e=>{console.error(e.stack||e);process.exit(1)});
